In order to use WorkManager, we need to make some changes to the existing code. Here's the updated class using WorkManager:

```kotlin
import android.app.Application
import android.content.Context
import android.util.Log
import androidx.work.Worker
import androidx.work.WorkerParameters

class TripDataSyncTask(context: Context, workerParams: WorkerParameters) : Worker(context, workerParams) {

    enum class Status { SUCCESS, CANCELLED, ABORTED }

    companion object {
        private val TAG = TripDataSyncTask::class.java.simpleName
    }

    override fun doWork(): Result {
        Log.d(TAG, "Starting work")
        val application: Application = applicationContext as Application
        val mode = MyPNR.getInstance().mode

        if (mode == MyPNR.Mode.TRAIN) {
            val userWifiPref: Boolean = inputData.getBoolean("userWifiPref", false)
            val userDataPref: Boolean = inputData.getBoolean("userDataPref", false)

            if (!userDataPref && NetworkUtils.isConnectedMobile(application)) {
                Log.d(TAG, "Stopping work because mobile data not available")
                return Result.failure()
            }

            if (!userWifiPref && NetworkUtils.isConnectedWifi(application)) {
                Log.d(TAG, "Stopping work because wifi not available")
                return Result.failure()
            }
        }

        val activeTrips = ItineraryHelper.getActiveTrips(application, TravelItinerary::class.java)

        Log.d(TAG, "Active Trips : ${activeTrips.size}")

        val tripsToBeHandled = getTripsToBeHandled(activeTrips.toMutableList())

        Log.d(TAG, "Trips to be handled : ${tripsToBeHandled.size}")

        for (trip in tripsToBeHandled) {
            Log.i(TAG, "Handling PNR: " + trip.pnr)
            NotificationHandler.handleChain(application, trip)
            if (isStopped) return Result.failure()
        }

        val syncHelper = TripSyncHelper(application)
        if (mode == MyPNR.Mode.FLIGHT) {
            syncHelper.sync()
        } else if (mode == MyPNR.Mode.TRAIN && IxiAuth.getInstance().isLoggedIn) {
            syncHelper.sync(Constant.INTERVAL_TWO_HOURS)
        }

        return Result.success()
    }

    // Filters out trips that required handling
    private fun getTripsToBeHandled(activeTrips: MutableList): List =
        activeTrips.map { it as TravelItinerary }.filter { isRefreshRequired(it) }

    private fun isRefreshRequired(trip: TravelItinerary): Boolean {
        try {
            if (trip.lastUpdated == null) {
                return true
            }

            val timeSinceLastCheck = System.currentTimeMillis() - trip.lastUpdated.time
            val timeTillJourney = trip.journeyDate.time - System.currentTimeMillis()

            if (timeSinceLastCheck < Constant.MIN_ELAPSED_TIME_BEFORE_RESYNC) {
                return false
            }

            if (!trip.isCanceled) {
                if (timeTillJourney >= Constant.INTERVAL_ONE_WEEK) {
                    if (timeSinceLastCheck >= Constant.INTERVAL_TWELVE_HOURS) {
                        return true
                    }
                } else if (timeTillJourney >= Constant.INTERVAL_TWO_DAYS) {
                    if (timeSinceLastCheck >= Constant.INTERVAL_SIX_HOURS) {
                        return true
                    }
                } else if (timeTillJourney >= Constant.INTERVAL_ONE_HOUR) {
                    if (timeSinceLastCheck >= Constant.INTERVAL_FORTY_FIVE_MINUTES) {
                        return true
                    }
                }
            }

            return false
        } catch (e: Exception) {
            e.printStackTrace()
            return true
        }
    }
}

```

To schedule this worker:

```kotlin
