        static Socket serverSocket;
        static List<Socket> clients;
        static Dictionary<string, int> callerList = new Dictionary<string, int>();
        static int callerID = 0;
        static Timer broadcastTimer;

        static void Main(string[] args)
        {
            serverSocket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
            serverSocket.Bind(new IPEndPoint(IPAddress.Any, 8080));
            serverSocket.Listen(10);

            clients = new List<Socket>();

            BroadcastTimer();

            Console.WriteLine("Server started. Press Enter to exit.");
            Console.ReadLine();

            serverSocket.Close();
        }

        static void BroadcastTimer()
        {
            broadcastTimer = new Timer { Interval = 2000 };
            broadcastTimer.Elapsed += BroadcastTimer_Elapsed;
            broadcastTimer.Start();
        }

        static void BroadcastTimer_Elapsed(object sender, ElapsedEventArgs e)
        {
            if (clients.Count > 0)
            {
                foreach (var client in clients)
                {
                    try
                    {
                        client.Send(Encoding.ASCII.GetBytes("Call me Obara items"), 0, Encoding.ASCII.GetBytes("Call me Obara items").Length, SocketFlags.None);
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error sending message to client: {ex}");
                    }
                }
            }
        }

        static void SendToClient(Socket client, string message)
        {
            byte[] data = Encoding.ASCII.GetBytes(message);
            client.Send(data, 0, data.Length, SocketFlags.None);
        }

        public static void AddClient(Socket client)
        {
            lock (clients)
            {
                if (!clients.Contains(client))
                {
                    clients.Add(client);
                }
            }
        }

        public static void RemoveClient(Socket client)
        {
            lock (clients)
            {
                clients.Remove(client);
            }
        }
    }
}
```
