class ZipHelper
{
    public static string gzipCompressString($rawString)
    {
        if ( empty($rawString) || $rawString == '') {
            return '';
        }
        $rawData = utf8_encode($rawString);
        $zippedData = gzipCompress($rawData);
        return base64_encode($zippedData);
    }

    public static byte[] gzipCompressStr2byte($rawString)
    {
