            return null;
        }
        $rawData = utf8_encode($rawString);
        $zippedData = gzipCompress($rawData);
        return $zippedData;
    }

    public static byte[] gzipDecompressString($zippedString)
    {
        if ( empty($zippedString) || $zippedString == '') {
            return '';
        }
        $zippedData = base64_decode($zippedString);
        return gzipDecompress($zippedData);
    }

    public static byte[] gzipDecompress($zippedData)
    {
        $gz = new Gzsocket();
        $stream = $gz->factory(GzipStream::DECOMPRESS);
        $stream->write($zippedData, 0, strlen($zippedData));
