To create a NextJS page that accepts CSV, XLS, and XLSX files, processes them in a NextJS API route, and saves the contents to Supabase, follow these steps:

1. Install the required packages:
```
npm install xlsx papaparse supabase supabase-js
```

2. Create a new file called `upload.js` inside the `pages` directory:

```javascript
// pages/upload.js
import { createClient } from '@supabase/supabase-js'

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY
)

export default function UploadPage() {
  const handleFileUpload = async (e) => {
    const file = e.target.files[0]
    if (!file) return

    const formData = new FormData()
    formData.append('file', file)

    const response = await fetch('/api/process-file', {
      method: 'POST',
      body: formData
    })

    if (response.ok) {
      alert('Data successfully saved to Supabase')
    } else {
      alert('Error processing the file')
    }
  }

  return (
    <div>
      <h1>Upload a CSV/XLS/XLSX File</h1>
      <input type="file" accept=".csv,.xls,.xlsx" onChange={handleFileUpload} />
    </div>
  )
}
```

3. Create a new file called `process-file.js` inside the `pages/api` directory:

```javascript
// pages/api/process-file.js
import { Readable } from 'stream'
import { createClient } from '@supabase/supabase-js'
import { finished } from 'stream/promises'
import XLSX from 'xlsx'
import {Papa} from 'papaparse'

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY
)

const processData = async (data) => {
  // Here, you can choose to save the data in a specific table and with specific columns
  const { error } = await supabase.from('your_table').insert(data)

  if (error) throw error
}

export const config = {
  api: {
    bodyParser: false,
  },
}

export default async (req, res) => {
  try {
    const fileStream = new Readable({ read() {} })
    fileStream.wrap(req)

    // Wait until the file upload is completed before processing the contents
    const buffer = await finished(fileStream)

    const fileType = req.headers['content-type']

    let data
    if (fileType === 'text/csv') {
      Papa.parse(buffer.toString(), {
        header: true,
        complete: async (results) => {
          data = results.data
          await processData(data)
          res.status(200).json({ message: 'File processed successfully' })
        },
        error: (error) => {
          res.status(500).json({ error: 'Error processing the file' })
        },
      })
    } else if (['application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(fileType)) {
      const workbook = XLSX.read(buffer, { type: 'buffer' })
      const sheetName = workbook.SheetNames[0]
      const worksheet = workbook.Sheets[sheetName]
      data = XLSX.utils.sheet_to_json(worksheet)

      await processData(data)
      res.status(200).json({ message: 'File processed successfully' })
    } else {
      res.status(400).json({ error: 'Invalid file format' })
    }
  } catch (error) {
    console.error(error)
    res.status(500).json({ error: 'Error processing the file' })
  }
}
```

4. Replace `'your_table'` with your table name in the `processData` function in `process-file.js`.

5. Add your Supabase URL and API key in your `.env.local` file:
```
NEXT_PUBLIC_SUPABASE_URL=your_supabase_url
NEXT_PUBLIC_SUPABASE_ANON_KEY=your_supabase_anon_key
```

Now, when you visit `/upload` in your NextJS application, you can upload a CSV, XLS, or XLSX file, and the contents will be processed and saved to your Supabase table.

Remember to replace the placeholders such as `'your_table'`, `'your_supabase_url'`, and `'your_supabase_anon_key'` with your specific values.

