	data, err := fetchTempAnomaliesData()
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	err = plotData(data)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
}

func fetchTempAnomaliesData() ([]GlobalTempAnomaly, error) {
	url := "https://datahub.io/core/global-temp/r/annual.csv"
	response, err := http.Get(url)
	if err != nil {
		return nil, err
	}
	defer response.Body.Close()

	reader := csv.NewReader(response.Body)
	reader.Read() // Ignore headers
	data := make([]GlobalTempAnomaly, 0)

	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		} else if err != nil {
			return nil, err
		}

		year, _ := strconv.Atoi(record[0])
		value, _ := strconv.ParseFloat(record[1], 64)

		data = append(data, GlobalTempAnomaly{
			Year:  year,
			Value: value,
		})
	}

	return data, nil
}

func plotData(data []GlobalTempAnomaly) error {
	p, err := plot.New()
	if err != nil {
		return err
	}

	p.Title.Text = "Global Temperature Anomalies"
	p.X.Label.Text = "Year"
	p.Y.Label.Text = "Temperature Anomaly (°C)"

	plotData := make(plotter.XYs, len(data))
	for i, v := range data {
		plotData[i] = plotter.XY{
			X: float64(v.Year),
			Y: v.Value,
		}
	}

	err = plotutil.AddLinePoints(p, "GlobalTempAnomalies", plotData)
	if err != nil {
		return err
	}

	err = p.Save(12*vg.Inch, 6*vg.Inch, "global_temp_anomalies.png")
	if err != nil {
		return err
	}

	fmt.Println("Plot saved as global_temp_anomalies.png")
	return nil
}
